type Patch=Partial<ProjectRecord>;
const D:Record<string,Patch>={
'manufacturing-line':{
 title:'Truffle Packaging Line', category:'Industrial automation × machine vision', status:'Team course project, RAS 102',
 summary:'A miniature factory that sorts 3D-printed chocolate truffles by shape and colour, boxes them, and caps the box with no one touching it.',
 overview:'Seven of us built this for RAS 102 through the School of Manufacturing Systems and Networks at ASU, and showed it at the ASU Innovation Showcase in May 2026. We designed and 3D-printed 12 different truffle shapes, plus multicolour boxes, insert trays and loading fixtures. A vision system picks out each truffle by shape and colour and sorts it into the box. A person can correct the AI during a run, and the model trains on that correction live. Once a box is full it rides a conveyor. An IR sensor triggers an Arduino Opta PLC, and two Dobot arms cap the box in sequence, lift it off the belt and set it in a drop-off spot. My part was the communication between the Dobot arms and the Opta, and the baseline control code the rest of the team built on.',
 features:['12 custom 3D-printed truffle designs, shaped so a robot arm and a camera can both handle them.','Vision that recognises each truffle by shape and colour, with a human-in-the-loop correction that retrains the model during the run.','Custom multicolour boxes, insert trays and robotic loading fixtures.','An Arduino Opta PLC that sequences the stations and tracks production state.','Dobot Magician Lite arms with a dedicated job each: sorting, loading, capping, removal from the conveyor.'],
 stack:['Arduino Opta PLC','Dobot Magician Lite','Python','Computer vision','CAD + 3D printing','IR sensor','Conveyor'],
 flow:['Sort truffles by shape and colour with the vision system.','Load them into the custom box, then verify the box.','Move the box down the conveyor; the IR sensor trips the PLC.','The PLC runs the capping and removal sequence on the two Dobot arms, ending at the drop-off.'],
 limits:'A team of seven: Ela Chachulski, Sara Doyle, Isabella Hamamoto, Ana Moisa, Luis Valledor, Makenna Walker and me, with Prof. Jake Okun and Prof. Sangram Redkar guiding. It is a classroom-scale line, not a production cell. The PLC-to-Dobot control code is in the public repo linked on the Dobot + Opta PLC page.',
 sources:[{label:'Sara Doyle, project post (May 23, 2026)',href:'https://www.linkedin.com/posts/sara-doyle-285458382_robotics-automation-plc-activity-7463790862519545856-TjTP'},{label:'Ela Chachulski, Innovation Showcase post (May 19, 2026)',href:'https://www.linkedin.com/posts/elachachulski_asu-innovationshowcase-automation-activity-7462547668884414464-0jH_'}],note:''},
'dobot-plc':{
 title:'Dobot + Opta PLC', category:'Industrial automation', status:'Control layer for the truffle line',
 summary:'Four Dobot arms that never talk to each other. Every handshake goes through the PLC, like a real line.',
 overview:'The Dobot Magician Lite has no documented way to take commands from an industrial PLC, and the Opta was new. We skipped the educational wrapper and drove each arm through the raw DobotDllType library, then wired the arms to the Opta over GPIO: pin 16 on each Dobot is the PLC "start" input and pin 22 is the "done" output. An IR proximity sensor on the conveyor starts cycle one. When a Dobot finishes it raises "done", the PLC routes that signal to the next Dobot, and the chain keeps going down the line. Each arm runs its own Python script in its own terminal, so a stage can be changed or restarted without touching the others.',
 features:['Opta sketch in C++ with chained triggers: digital outputs D0-D3 start the arms, analog inputs A0-A2 read their done signals, A6 and A7 read the IR sensors.','Dobot 1 is a vision sorter: OpenCV HSV colour segmentation and a Random Forest classifier trained on shape features.','Dobots 2 and 4 run taught pick-and-place routines with named positions and PLC handshakes.','Dobot 3 uses a "series" idea: several task lists that advance one by one on each PLC trigger.','A text teach menu (teach, list, test-move, reorder tasks, run the conveyor) and a CustomTkinter dashboard to connect, home and play.'],
 stack:['Arduino Opta (C++)','Python','DobotDllType','OpenCV + scikit-learn','Digital I/O','Stepper conveyor'],
 flow:['An object passes the IR sensor and the Opta raises D1.','Dobot 1 runs its task list, then pulses pin 22 as "done".','The Opta sees the done signal and starts Dobot 2.','The same handshake carries on down the line.'],
 limits:'Built for the RAS 102 truffle line with the MSN team. I wrote the arm-to-PLC communication and the baseline code; teammates handled the rest of the cell. Common ground between the PLC and all four arms matters, because the I/O is read as raw voltage. Source: public repo.',note:''},
'microtube-insertion':{
 title:'Well, Honey! Microtube Insertion', category:'Heat-exchanger manufacturing', status:'3rd place, Honeywell x ASU Devils Invent 2026',
 summary:'Heat exchangers need thousands of thin tubes pushed through a plate. We tried to make the plate do the aligning instead of a robot.',
 overview:'Our team took third place and a $2,500 prize at the 2026 Honeywell x ASU Devils Invent hackathon, theme "Optimized and Intelligent Control Systems". The problem: inserting thousands of delicate tubes into a tubesheet is manual, slow, skill-dependent and prone to rework. Instead of a robot that places one tube at a time, we made the geometry do it. Cone-shaped, chamfered holes guide each tube in, controlled vibration helps the tubes settle into alignment, and a linear actuator separates the plates afterwards. We 3D-printed prototypes to show it working. Our line from the pitch: "We\'re not replacing the system, we\'re removing its biggest bottleneck."',
 features:['Chamfered, cone-shaped guide holes so a tube finds its slot without exact placement.','Controlled vibration so tubes self-align.','A linear actuator to separate the plates after insertion.','3D-printed physical prototypes, with a pitch deck and demo footage in the repo.'],
 stack:['Mechanical design','3D printing','Vibration','Linear actuator'],
 flow:['Lay the guide plate over the tubesheet.','Vibrate so the tubes settle into the chamfers.','Insert, then separate the plates with the actuator.'],
 limits:'Team: Prajval Arora, L Johnson, Toshan Jagani, Riya Mehta and Sameerjeet Singh Chhabra. This is a hackathon prototype, shown at bench scale; there are no throughput numbers. My repo is a fork of Sameerjeet\'s team repository.',note:''},
'air-guitar':{
 summary:'Wrist angle picks the string, a flick of the wrist plucks it. The sound is synthesised from scratch.',
 overview:'I built this right after the Air Mouse, because the same sensor could do something more fun. A small MPU6050 on my wrist streams roll angle and acceleration through an Arduino Uno at 115200 baud, in a simple ROLL:FORCE format. A Python script treats certain angles as invisible strings in open E tuning. When my wrist crosses one with enough acceleration, it plucks that string using the Karplus-Strong algorithm, a short loop of filtered noise that sounds like a real string, and mixes the result in real time with NumPy and sounddevice. Harder flicks play louder. It recalibrates its zero angle on startup. For the demo video I set six notes based on one song, since I don\'t actually play guitar.',
 features:['Karplus-Strong string synthesis in Python, mixed live through sounddevice.','Six virtual strings in open E tuning chosen by wrist angle.','Strum force from acceleration controls how hard the note plays.','Auto-calibration of the neutral wrist position at startup.'],
 limits:'Needs the sensor on the wrist and a computer for sound. Proof of concept: it plays a handful of notes, not chords or full songs.',
 sources:[{label:'Public source repository',href:'https://github.com/RoboX2020/Air-Guitar'},{label:'Demo video on LinkedIn (Dec 2025)',href:'https://www.linkedin.com/posts/prajvalarora_guitar-arduino-tech-ugcPost-7404269130801012736-yHCj/'}]},
'air-mouse':{
 summary:'A motion sensor on my glasses moves the cursor wherever I point my head.',
 overview:'I was bored of a regular mouse one day in November 2025, so I mounted an MPU sensor, the kind used in drones, on a pair of glasses. An Arduino reads its motion and a button input and streams it over USB serial. A Python listener scales the motion into cursor movement and presses the left mouse button with pynput. The whole prototype took about an hour, and AI wrote much of the code while I steered the idea and debugged. The thing I took from it: AI speeds up the build, but the idea of where to put the sensor still has to come from you. Several people commented that it points with the head, not the eyes. That is right, and it is why the click is a separate button.',
 features:['MPU motion sensor mounted on glasses.','Arduino sends X/Y motion and click state over serial.','Python converts motion into pointer movement and left-click through pynput.'],
 limits:'Head-pointing, not eye tracking. A one-hour prototype with no calibration or smoothing work beyond scaling. It also led directly to the Air Guitar.',
 sources:[{label:'Public source repository',href:'https://github.com/RoboX2020/Air-Mouse'},{label:'Build post on LinkedIn (Nov 2025)',href:'https://www.linkedin.com/posts/prajvaldesignsmachines_ai-tech-innovation-activity-7399010092685139968-g50Q'}]},
'caricature-drawing':{
 overview:'A terminal app that turns any photo into line art and has a Dobot Magician Lite draw it. You press C to calibrate: four points, pen-down height, pen-up height, and the bottom-left and top-right corners of the paper. Press I to load an image and pick a detail level from 1 to 5. OpenCV finds edges with Canny, turns the contours into continuous single-line strokes, and a G-code generator maps those pixels onto the calibrated paper. It shows a preview before the arm moves, and D starts the drawing. Ctrl+C is an emergency stop that lifts the pen first.',
 features:['Canny edge detection and contour optimisation with five detail levels.','Four-point calibration wizard for pen heights and paper corners, saved between sessions.','Pixels mapped to the physical paper area and converted to G-code style coordinates.','Preview before any motion, and an emergency stop that raises the pen.'],
 limits:'It traces edges. It does not caricature or exaggerate features; the "caricature" name comes from where the idea started. I tested it on my own portrait.'},
'air-piano':{
 overview:'A webcam and MediaPipe\'s hand-landmark model find up to two hands. Thumb and fingertip coordinates are mapped onto an on-screen keyboard, and a separate audio engine plays the note when a fingertip lands on a key. Vision and sound run as separate modules (vision_engine.py, audio_engine.py), so either can be swapped. It needs the hand_landmarker.task model and a set of downloaded sound samples.',
 limits:'A webcam prototype. I have not measured its latency, and it plays single notes rather than whole pieces.'},
'celialife':{
 overview:'CeliaLife is a personal health record. You upload PDFs and photos of medical documents, it extracts the text, summarises each one with GPT-4o, and lets you ask questions about your history with those documents as context. The idea is that a patient, or a doctor reviewing, can see disease risks surfaced from a long history. It is a full-stack app: React, Vite, Tailwind and shadcn on the front, Express with PostgreSQL (Neon) and Drizzle on the back, and Google sign-in through OpenID Connect. It is set up for serverless deployment on Vercel.',
 limits:'A prototype, not a medical device. It does not diagnose, and the risk summaries are AI output meant for a doctor to review. No clinical validation, and there is no public demo because it would hold health data.'},
'kalki':{
 overview:'Kalki is a place to raise a local problem and get people behind it. Each post has a description, a goal, the demands, and guiding tenets, with a discussion drawer on every post. It came out of Google AI Studio and I built it out in React and TypeScript, with Firebase for sign-in and a store layer for the posts. It ships with a manifesto and example posts.',
 limits:'A prototype with example data. It has no real community behind it yet.'},
'partyplay':{
 overview:'Think of an arcade cabinet that lives on everyone\'s phones. A host opens PartyPlay on a TV or projector and shows a QR code and room code. Players scan, join a queue, and whoever is first plays on their own phone while the TV shows their game live, as a JPEG stream of the phone\'s canvas at about 8 frames per second. When the run ends, the score goes up on a hall of fame and the next person is up automatically. Six canvas games: Street Racer, Power Cricket, Sky Hopper, Gravity Run, Stack Tower and Brick Breaker. It runs on Node, Express and Socket.IO with plain HTML, CSS and JavaScript. I originally built it as a Kahoot-style multiplayer game; that version is kept in a backup folder.',
 limits:'One player at a time, 8 fps streaming, run on a local network. No public hosted version.'},
'esp32-ai-robot':{
 overview:'A small desk robot on an ESP32-C3 Super Mini. A 0.96-inch OLED shows animated eyes that blink, look around and change with mood, including a Spider-Man mask. A piezo buzzer plays sound. The ESP32 serves its own web controller over WebSockets, with speech-to-text, so you talk to it from a phone or laptop and GPT-4o answers. You can ask it to make a Pong or Flappy Bird game and it streams the generated game to the OLED, or ask for the Mario theme or Imperial March as 8-bit tunes. It also has a chat mode for reading long answers and a caption mode that shows text one word at a time.',
 limits:'Needs Wi-Fi and an OpenAI key; it does not work offline. Hobby build; I make no claim that generated games are safe to run on other hardware.'},
'esp-claw':{
 overview:'ESP-Claw is Espressif\'s "Chat Coding" AI agent framework for IoT chips. An Arduino Uno has too little memory to run it, so in my pull request (#11, opened April 24, 2026) the work is split in two. The Uno runs small firmware that executes JSON commands over serial: GPIO read/write, analog and PWM, up to four servos, and I2C read, write and scan. A host-side Python bridge exposes that hardware through a command line and an API, and ai_shell.py lets you program the board in plain English using OpenAI or Anthropic models. The PR changes 17 files and adds about 2,200 lines, with documentation.',
 limits:'The PR is open and unreviewed. It is not merged and Espressif has not endorsed it.'},
'vibeverse':{
 overview:'VibeVerse was a showcase site for projects built with AI: share what you made, browse what others made, remix an idea, and ship your own. I launched it on Product Hunt on May 7, 2026, and the listing went live. The site was vibeverseai.com.',
 limits:'The code repository is private and I do not have screenshots to show. The Product Hunt launch is the public record.',sources:[{label:'Launch post on LinkedIn (May 7, 2026)',href:'https://www.linkedin.com/posts/prajvalarora_the-showcase-platform-for-vibe-coded-ai-projects-activity-7458058955186126848-WPwg'}]},
'ar-speech-therapy':{
 title:'AR Speech Therapy', category:'Wearable AI × clinical research', status:'Reached clinical testing',
 summary:'A wearable that listens to a patient, sees what they see, and coaches their speech through an AR display.',
 overview:'At the Barrow Institute in Arizona I built an AR-assisted speech therapy device with Dr. Catherine\'s research team. The patient wears a birdbath AR display. A Jetson Nano runs a language model locally and a stereo camera provides vision. For aphasia patients it listens to their attempt at a word and guides pronunciation. For apraxia patients it narrates their surroundings to support context and comprehension. My side was the hardware integration, camera calibration, the vision pipeline and the speech-correction logic, in C++ and Python prototypes. It reached clinical testing while I was on the project, and the team was looking at forming an LLC. The project then went quiet, so I cannot say where it stands today.',
 features:['Jetson Nano running language-model inference on the device.','Stereo camera with calibration for the vision pipeline.','Birdbath AR display worn by the patient.','Two modes: pronunciation guidance for aphasia, continuous scene narration for apraxia.'],
 stack:['Jetson Nano','Stereo vision','Local LLM','AR display','C++','Python'],flow:[],
 limits:'Sept 2025 to Mar 2026 at Barrow Institute. A research device that was in clinical testing during my time on it, not an approved medical product. I have no current-status update. Patient data stays out of this site.',note:''},
'stellantis-cell':{
 title:'Stellantis Dual-URSe Cell', category:'Industrial robotics × digital twins', status:'In build, ASU x Wandelbots',
 summary:'A two-cobot demonstrator for a Stellantis event in Detroit, with its twin running in simulation.',
 overview:'ASU and Wandelbots asked for a demonstrator for a Stellantis event in Detroit. I am building the dual-URSe industrial cell: two cobots, the end-effectors, machine vision and the cell network, with Isaac Sim digital twins to validate the setup before and during commissioning. Work started in August 2026.',
 limits:'Still in build, so there are no results or photos to show yet.',note:''},
'unitree-go2':{
 overview:'I train a Unitree Go2 quadruped in NVIDIA Isaac Sim with reinforcement learning, aiming for walking and a flip, using ROS 2, Isaac Sim and Omniverse workflows and a digital twin. The clip shows many robots training in parallel. Separately, my Go2 lab report has a PyBullet exploration with depth, RGB and lidar panels, labelled as PyBullet because it is not Isaac Sim.',
 limits:'Training goals, not a finished policy. I have not run the robot itself, so sim-to-real transfer is still ahead.',note:''},
'spider-robot':{
 overview:'A system that links a language model directly to hardware. You tell a spider robot what to do in plain language, and the model turns the command into coordinated multi-leg movement.',
 limits:'An early hardware experiment. I have no demo footage or measurements to show yet.',note:''},
'euler-ai':{
 overview:'Euler Ai is an animation agent for math teachers. You describe a concept in text and it produces a Desmos-style visualisation of it on a Mafs canvas, with OpenAI generating the scene.',
 limits:'Early prototype. Generation quality varies with the prompt, and there is no gallery or save flow.',note:''},
'arms-asu':{
 overview:'ARMS (Advanced Robotics & Manufacturing Systems) is a student-led engineering organisation at ASU Polytechnic, run with the School of Manufacturing Systems and Networks. It takes on projects for industry and contracts with companies, with the aim of speeding up innovation at ASU. I am one of the people building it, on the finance, marketing and software side. Separately, I am working with Drone Devils on a plane, a boat and an FPV car.',
 limits:'An organisation, not a single build. The robot photos live on the individual project pages.',note:''}
};
